/* @autogenerated */
import { Component, ErrorHandler } from '@angular/core';
import { TestBed, fakeAsync, tick } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { of, throwError } from 'rxjs';
import { TranslocoService } from '@jsverse/transloco';
import { SpanStatusCode } from '@opentelemetry/api';
import { ErrorService, GlobalErrorHandler, handledErrors, markErrorHandled } from './error.service';
import { Logger } from './logger.service';
import { InstrumentationService } from './instrumentation.service';
import { IdentityService } from '../identity/identity.service';

describe('ErrorService', () => {
  let service: ErrorService;
  let snackBar: jasmine.SpyObj<MatSnackBar>;
  let dialog: jasmine.SpyObj<MatDialog>;
  let mockSpan: any;
  let provider: any;
  let logger: jasmine.SpyObj<Logger>;
  let identity: jasmine.SpyObj<IdentityService>;
  let transloco: { translate: jasmine.Spy };

  beforeEach(() => {
    logger = jasmine.createSpyObj<Logger>('Logger', ['error']);
    identity = jasmine.createSpyObj<IdentityService>('IdentityService', ['login']);
    transloco = { translate: jasmine.createSpy('translate').and.callFake((key: string) => `t(${key})`) };
    mockSpan = {
      setStatus: jasmine.createSpy('setStatus'),
      recordException: jasmine.createSpy('recordException'),
      end: jasmine.createSpy('end'),
      spanContext: () => ({ traceId: '0af7651916cd43dd8448eb211c80319c', spanId: 'b7ad6b7169203331', traceFlags: 1 }),
    };
    snackBar = jasmine.createSpyObj('MatSnackBar', ['open']);
    snackBar.open.and.returnValue({ afterDismissed: () => of({ dismissedByAction: false }) } as any);
    dialog = jasmine.createSpyObj('MatDialog', ['open']);
    dialog.open.and.returnValue({ afterClosed: () => of(undefined) } as any);
    provider = { startSpan: jasmine.createSpy('startSpan').and.returnValue(mockSpan) };

    TestBed.configureTestingModule({
      providers: [
        ErrorService,
        { provide: MatDialog, useValue: dialog },
        { provide: MatSnackBar, useValue: snackBar },
        { provide: Logger, useValue: logger },
        { provide: InstrumentationService, useValue: provider },
        { provide: IdentityService, useValue: identity },
        { provide: TranslocoService, useValue: transloco },
      ],
    });
    service = TestBed.inject(ErrorService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('notifyError opens a snackbar with the given message', () => {
    service.notifyError('Something went wrong');
    expect(snackBar.open).toHaveBeenCalledWith('Something went wrong', 't(common.confirm.ok)', { duration: 5000 });
  });

  it('notifyError falls back to the translated generic message', () => {
    service.notifyError();
    expect(snackBar.open).toHaveBeenCalledWith('t(errors.generic)', 't(common.confirm.ok)', { duration: 5000 });
  });

  it('initializeError does not mutate the error', () => {
    const error: any = {};
    service.initializeError(error);
    expect(Object.keys(error)).toEqual([]);
    service.cancelError(error);
  });

  it('isPending is true until the notice is shown', fakeAsync(() => {
    const error = {};
    expect(service.isPending(error)).toBeFalse();
    service.initializeError(error);
    expect(service.isPending(error)).toBeTrue();
    tick(2000);
    expect(service.isPending(error)).toBeFalse();
  }));

  it('cancelError discards the pending notice', fakeAsync(() => {
    const error = {};
    service.initializeError(error);
    service.cancelError(error);
    expect(service.isPending(error)).toBeFalse();
    tick(2000);
    expect(dialog.open).not.toHaveBeenCalled();
  }));

  it('initializeError opens the dialog after 2 seconds', fakeAsync(() => {
    const error: any = {};
    service.initializeError(error);
    tick(1999);
    expect(dialog.open).not.toHaveBeenCalled();
    tick(1);
    expect(dialog.open).toHaveBeenCalled();
    expect(dialog.open.calls.mostRecent().args[1]).toEqual({ data: { error, login: undefined } });
  }));

  it('initialiceError is kept as a deprecated alias', fakeAsync(() => {
    service.initialiceError({});
    tick(2000);
    expect(dialog.open).toHaveBeenCalled();
  }));

  it('initializeError offers to sign in with the identity of a 401', fakeAsync(() => {
    const error: any = { status: 401, identity: 'main' };
    service.initializeError(error);
    tick(2000);
    const data = dialog.open.calls.mostRecent().args[1]!.data as any;
    expect(data.error).toBe(error);
    expect(identity.login).not.toHaveBeenCalled();
    data.login();
    expect(identity.login).toHaveBeenCalledWith('main');
  }));

  it('initializeError does not offer to sign in for a 401 without identity', fakeAsync(() => {
    service.initializeError({ status: 401 });
    tick(2000);
    expect((dialog.open.calls.mostRecent().args[1]!.data as any).login).toBeUndefined();
  }));

  it('initializeError shows a translated snackbar for 422 errors', fakeAsync(() => {
    service.initializeError({ status: 422 });
    tick(2000);
    expect(snackBar.open).toHaveBeenCalledWith('t(errors.422)', undefined, { duration: 2000 });
    expect(dialog.open).not.toHaveBeenCalled();
  }));

  it('initializeError shows nothing for an error marked as handled', fakeAsync(() => {
    const error = { status: 500 };
    service.initializeError(error);
    markErrorHandled(error);
    tick(2000);
    expect(dialog.open).not.toHaveBeenCalled();
    expect(provider.startSpan).not.toHaveBeenCalled();
  }));

  it('handledErrors suppresses the global notice for the given statuses and rethrows', fakeAsync(() => {
    const error = { status: 422 };
    const received: unknown[] = [];
    service.initializeError(error);
    throwError(() => error)
      .pipe(handledErrors([422]))
      .subscribe({ error: (e) => received.push(e) });
    tick(2000);
    expect(received).toEqual([error]);
    expect(snackBar.open).not.toHaveBeenCalled();
  }));

  it('handledErrors lets other statuses reach the global notice', fakeAsync(() => {
    const error = { status: 500 };
    service.initializeError(error);
    throwError(() => error)
      .pipe(handledErrors([422]))
      .subscribe({ error: () => undefined });
    tick(2000);
    expect(dialog.open).toHaveBeenCalled();
  }));

  it('storeError records a span with ERROR status and the error message', () => {
    const error = { message: 'oops' };
    service.storeError(error);

    expect(provider.startSpan).toHaveBeenCalledWith('oops');
    expect(mockSpan.setStatus).toHaveBeenCalledWith({ code: SpanStatusCode.ERROR, message: 'oops' });
    expect(mockSpan.recordException).toHaveBeenCalledWith(error);
    expect(mockSpan.end).toHaveBeenCalled();
    expect(logger.error).toHaveBeenCalledWith('Unhandled error', error);
  });

  it('storeError uses a fallback message when error has no message', () => {
    service.storeError({});
    expect(provider.startSpan).toHaveBeenCalledWith('Unspecified error');
  });

  it('storeError creates exactly one span per error', () => {
    service.storeError({ message: 'a' });
    service.storeError({ message: 'b' });
    expect(provider.startSpan).toHaveBeenCalledTimes(2);
    expect(mockSpan.end).toHaveBeenCalledTimes(2);
  });

  it('storeError records the same error only once', fakeAsync(() => {
    const error = { message: 'oops', status: 500 };
    service.storeError(error); // p. ej. el GlobalErrorHandler, porque nadie capturó el error HTTP
    service.initializeError(error);
    tick(2000);
    expect(provider.startSpan).toHaveBeenCalledTimes(1);
    expect(dialog.open).toHaveBeenCalled();
  }));

  it('storeError annotates the error with the traceId for support', () => {
    const error: any = { message: 'oops' };
    service.storeError(error);
    expect(error.traceId).toBe('0af7651916cd43dd8448eb211c80319c');
  });

  it('storeError does not annotate an invalid (no-op) trace', () => {
    mockSpan.spanContext = () => ({
      traceId: '00000000000000000000000000000000',
      spanId: '0000000000000000',
      traceFlags: 0,
    });
    const error: any = { message: 'oops' };
    service.storeError(error);
    expect(error.traceId).toBeUndefined();
  });
});

describe('GlobalErrorHandler', () => {
  it('delegates to ErrorService.storeError via the injector', () => {
    const storeError = jasmine.createSpy('storeError');
    const injector = { get: jasmine.createSpy('get').and.returnValue({ storeError }) };
    const handler = new GlobalErrorHandler(injector as any);

    handler.handleError({ message: 'boom' });

    expect(storeError).toHaveBeenCalledWith({ message: 'boom' });
  });
});

describe('GlobalErrorHandler registered as ErrorHandler', () => {
  @Component({ template: '<button (click)="boom()">boom</button>' })
  class FailingComponent {
    boom(): void {
      throw new Error('boom');
    }
  }

  it('receives the uncaught errors of a component', () => {
    const errors = jasmine.createSpyObj<ErrorService>('ErrorService', ['storeError']);
    TestBed.configureTestingModule({
      imports: [FailingComponent],
      providers: [
        { provide: ErrorHandler, useClass: GlobalErrorHandler },
        { provide: ErrorService, useValue: errors },
      ],
      rethrowApplicationErrors: false,
    });
    const fixture = TestBed.createComponent(FailingComponent);
    fixture.detectChanges();

    fixture.nativeElement.querySelector('button').click();

    expect(errors.storeError).toHaveBeenCalledWith(jasmine.objectContaining({ message: 'boom' }));
  });
});

describe('GlobalErrorHandler fallback', () => {
  it('logs to the console when the error cannot be stored', () => {
    const failure = new Error('no injector');
    const injector = {
      get: () => {
        throw failure;
      },
    };
    spyOn(console, 'error');

    new GlobalErrorHandler(injector as any).handleError({ message: 'boom' });

    expect(console.error).toHaveBeenCalledWith({ message: 'boom' }, failure);
  });
});
